from g123_core import make_q, make_lesson
from fig_helpers_g123 import table_fig, bars_fig, fig_clock, fig_traffic_sign


def _q(b, num, d, p, c, w, e, s='', h='', fig=None):
    return make_q(f'DD3-B{b:02d}-{num:03d}', d, p, c, w, e, s, h, fig)


def get_lessons_part1():
    lessons = []

    # BÀI 1: Chào cờ và hát Quốc ca trang nghiêm
    lessons.append(make_lesson(
        'daoduc3-c1', 'daoduc3-b01', 'Bài 1. Chào cờ và Hát Quốc ca Trang nghiêm', 1,
        'Hiểu ý nghĩa thiêng liêng của Quốc kì, Quốc ca Việt Nam và thực hiện nghiêm túc nghi thức Chào cờ đầu tuần thể hiện lòng yêu Tổ quốc',
        ['Yêu Tổ quốc Việt Nam', 'Nghi thức Chào cờ', 'Hát Quốc ca trang nghiêm'],
        [
            _q(1, 1, 'basic', 'Lá cờ Tổ quốc (Quốc kì) nước Cộng hòa Xã hội Chủ nghĩa Việt Nam có đặc điểm hình dáng và màu sắc như thế nào?', 'Hình chữ nhật nền đỏ thắm, ở giữa có ngôi sao vàng năm cánh lớn', ['Hình vuông nền xanh có vạch trắng', 'Hình tròn màu vàng có ngôi sao đỏ', 'Hình tam giác nền trắng viền xanh'],
               'Nền đỏ tượng trưng cho dòng máu anh hùng cách mạng; ngôi sao vàng năm cánh tượng trưng cho các tầng lớp nhân dân Việt Nam đoàn kết.', 'Quốc kì Việt Nam',
               fig=table_fig('Nghi thức Chào cờ', ['Yêu cầu', 'Thực hiện đúng chuẩn'], [['Trang phục', 'Gọn gàng, sạch đẹp'], ['Tư thế đứng', 'Nghiêm, hướng cờ'], ['Khi hát Quốc ca', 'Hát to, rõ, hào hùng'], ['Thái độ chung', 'Trang nghiêm, chú ý']])),
            _q(1, 2, 'basic', 'Bài Quốc ca chính thức của nước Việt Nam có tên gọi gốc là gì và do nhạc sĩ nào sáng tác?', 'Bài Tiến quân ca do nhạc sĩ Văn Cao sáng tác', ['Bài Em là mầm non của Đảng do Mộng Lân sáng tác', 'Bài Như có Bác trong ngày đại thắng do Phạm Tuyên sáng tác', 'Bài Bụi phấn do Vũ Hoàng sáng tác'],
               'Nhạc sĩ Văn Cao sáng tác bài Tiến quân ca năm 1944, trở thành Quốc ca bất hủ của dân tộc Việt Nam.', 'Quốc ca Tiến quân ca'),
            _q(1, 3, 'basic', 'Khi nghe hiệu lệnh "Nghiêm! Chào cờ, chào!", học sinh lớp 3 đang chuẩn bị vào nghi thức chào cờ đầu tuần cần giữ tư thế thế nào?', 'Đứng thẳng người nghiêm trang, hai tay đặt sát bên đùi (hoặc giơ tay chào kiểu Đội nếu đã là Đội viên), mắt hướng trang nghiêm lên lá Quốc kì', ['Đứng khoanh chân ngồi xổm xuống sân trường', 'Quay lưng lại nhìn bạn hàng bên cười đùa', 'Vừa đứng vừa ăn vặt uống trà sữa'],
               'Tư thế đứng nghiêm hướng về Quốc kì thể hiện niềm tự hào và lòng biết ơn Tổ quốc sâu sắc.', 'Tư thế khi Chào cờ'),
            _q(1, 4, 'basic', 'Trong lúc toàn trường cùng hát vang bài Quốc ca dưới lá cờ Tổ quốc, em cần hát với thái độ ra sao?', 'Hát đúng nhạc, đúng lời, âm lượng to rõ ràng, dứt khoát và hào hùng trang nghiêm', ['Chỉ mấp máy môi không phát ra tiếng cho đỡ mệt', 'Hát thật nhanh vượt trước nhạc để trêu bạn', 'Nói chuyện riêng át tiếng hát của cả lớp'],
               'Tiếng hát Quốc ca đồng thanh hào hùng khơi dậy tinh thần yêu nước mạnh mẽ trong mỗi học sinh.', 'Thái độ hát Quốc ca'),
            _q(1, 5, 'basic', 'Ngoài buổi lễ Chào cờ sáng thứ Hai tại sân trường, lá Quốc kì Việt Nam thường được treo trang trọng ở những nơi nào và vào dịp gì?', 'Tại trụ sở cơ quan nhà nước, trường học, quảng trường Ba Đình, các con tàu ngoài biển đảo và trước nhà dân vào các dịp lễ Tết lớn của dân tộc', ['Chỉ được treo duy nhất bên trong phòng ngủ', 'Dùng để trải dưới đất ngồi chơi', 'Chỉ treo vào ngày sinh nhật cá nhân'],
               'Treo Quốc kì đúng nơi trang trọng thể hiện chủ quyền thiêng liêng và niềm tự hào dân tộc Việt Nam.', 'Treo Quốc kì trang trọng'),
            _q(1, 6, 'basic', 'Khi đi học hơi trễ đúng lúc tiếng Quốc ca đã vang lên trang nghiêm trong lễ chào cờ tại sân trường, em bước vào cổng trường nên làm gì ngay?', 'Dừng bước ngay lập tức tại vị trí đứng gọn bên lề, đứng nghiêm hướng về phía lá cờ cùng hát Quốc ca cho đến khi dứt bài mới nhẹ nhàng đi vào hàng lớp', ['Chạy vội xuyên thẳng qua giữa hàng các lớp đang chào cờ', 'Nói lớn gọi tên bạn để xin vào hàng', 'Chui vào căng-tin trốn'],
               'Dừng bước đứng nghiêm khi Quốc ca vang lên là phép lịch sự và lòng tôn kính Tổ quốc chuẩn mực toàn cầu.', 'Ứng xử khi đến đúng lúc Quốc ca'),
            _q(1, 7, 'application', 'Sáng thứ Hai hàng tuần, trường tiểu học tổ chức lễ Chào cờ từ 7 giờ 15 (như mặt đồng hồ minh họa). Để cả lớp xếp hàng thẳng tắp chỉnh tề đồng phục trước giờ Chào cờ, bạn Nam cần có mặt tại sân trường muộn nhất lúc mấy giờ?', 'Khoảng 7 giờ 00 đến 7 giờ 05 phút sáng', ['Đúng 7 giờ 25 phút sáng', 'Đúng 8 giờ 00 sáng', 'Đúng 7 giờ 15 mới rời khỏi nhà'],
               'Có mặt sớm 10–15 phút sáng thứ Hai giúp em chỉnh trang đồng phục và sẵn sàng tinh thần trang nghiêm chào cờ.', 'Chuẩn bị lễ Chào cờ',
               fig=fig_clock(7, 15, 'Giờ bắt đầu lễ Chào cờ sáng thứ Hai')),
            _q(1, 8, 'application', 'Bạn Tí ngồi cạnh em trong giờ Chào cờ hay quay sang thì thầm rủ em kể chuyện phim hoạt hình khi cả trường đang hát Quốc ca. Em nên làm gì để vừa giữ kỉ luật nghi lễ vừa không gây ồn?', 'Ra hiệu nhẹ bằng ánh mắt nghiêm túc hoặc đặt ngón tay lên môi nhắc nhỏ bạn giữ im lặng, sau đó tiếp tục hướng mắt lên cờ hát Quốc ca trang nghiêm', ['Cãi nhau tay đôi thật to với Tí ngay giữa lễ Chào cờ', 'Quay sang kể chuyện phim cùng Tí cho vui', 'Đẩy Tí ngã ra khỏi hàng'],
               'Giữ sự trang nghiêm bằng cử chỉ tế nhị không làm gián đoạn nghi lễ chung của toàn trường.', 'Giữ trật tự trong nghi lễ'),
            _q(1, 9, 'application', 'Trong một cuộc thi "Tập thể Hát Quốc ca Hào hùng và Đều đẹp nhất" nhân dịp 20/11, ban giám khảo chấm điểm 4 lớp khối 3 dựa trên 3 tiêu chí (Trang phục – Tư thế – Giọng hát), tối đa 100 điểm. Theo biểu đồ điểm bên dưới, lớp nào đứng nhất khối?', 'Lớp 3B (đạt 98 điểm trên 100)', ['Lớp 3A (94 điểm)', 'Lớp 3C (92 điểm)', 'Lớp 3D (95 điểm)'],
               'Cột Lớp 3B cao nhất đạt 98 điểm xuất sắc toàn diện cả trang phục, tư thế và giọng hát!', 'Đọc biểu đồ thi đua Chào cờ',
               fig=bars_fig('Điểm thi Nghi thức Chào cờ Khối 3', ['Lớp 3A', 'Lớp 3B', 'Lớp 3C', 'Lớp 3D'], [94, 98, 92, 95], 'điểm')),
            _q(1, 10, 'application', 'Khi xem truyền hình trực tiếp một trận đấu bóng đá quốc tế của Đội tuyển Việt Nam, lúc Quốc ca Việt Nam vang lên trước trận đấu, gia đình em ngồi trước màn hình tivi nên thể hiện thái độ thế nào?', 'Cùng đứng dậy trang nghiêm đặt tay lên ngực trái và hát theo Quốc ca cổ vũ tinh thần cho các tuyển thủ nước nhà', ['Cười đùa chê bài hát dài quá', 'Chuyển kênh sang xem phim hài', 'Vẫn nằm dài gác chân lên ghế bấm điện thoại'],
               'Lòng tự hào dân tộc trong thể thao quốc tế gắn kết hàng triệu trái tim Việt Nam qua tiếng hát Quốc ca!', 'Hát Quốc ca khi xem thi đấu'),
            _q(1, 11, 'application', 'Trường em vừa thay lá Quốc kì mới trước cột cờ sân trường; lá cờ cũ hơi bạc màu được thầy Tổng phụ trách hạ xuống. Theo quy định tôn kính Quốc kì, lá cờ cũ không còn dùng nữa cần được xử lí thế nào?', 'Gấp gọn gàng cất giữ trang trọng trong phòng truyền thống nhà trường (hoặc thu hủy trang nghiêm theo quy định), không vứt bừa bãi', ['Ném thẳng vào thùng rác lẫn đồ ăn thừa', 'Mang ra làm giẻ lau bảng hay lau giày', 'Cắt nhỏ làm đồ chơi ném nhau'],
               'Quốc kì là biểu tượng thiêng liêng của quốc gia – trân trọng từng lá cờ là thể hiện lòng yêu nước chân thành!', 'Bảo quản Quốc kì đúng quy định'),
            _q(1, 12, 'application', 'Một bạn học sinh lớp 3 mới từ nước ngoài theo gia đình về Việt Nam học tập nên chưa thuộc hết lời bài Tiến quân ca. Là bạn cùng lớp, em giúp bạn thế nào?', 'Chép tặng lời bài hát rõ ràng, kiên nhẫn cùng bạn nghe và tập hát từng câu vào giờ giải lao để thứ Hai bạn tự tin hát vang cùng lớp', ['Cười chê bạn không thuộc Quốc ca', 'Cấm bạn ra sân chào cờ cùng lớp', 'Đẩy bạn đứng xuống cuối hàng'],
               'Giúp đỡ bạn hòa nhập tập hát Quốc ca lan tỏa tinh thần đoàn kết yêu nước thật ấm áp!', 'Hướng dẫn bạn hát Quốc ca'),
            _q(1, 13, 'advanced', 'Một năm học tiểu học có khoảng 35 tuần học chính thức, mỗi sáng thứ Hai toàn trường đều thực hiện nghi thức Chào cờ (trừ 2 tuần nghỉ lễ Tết trùng thứ Hai). Hỏi trong suốt năm học lớp 3, em được tham gia trực tiếp lễ Chào cờ đầu tuần tại sân trường khoảng bao nhiêu lần?', '33 lần', ['35 lần', '30 lần', '37 lần'],
               '35 - 2 = 33 lần nghi thức Chào cờ đầu tuần thiêng liêng dưới mái trường!', 'Thống kê nghi lễ năm học'),
            _q(1, 14, 'advanced', 'Vì sao trong nghi thức Chào cờ trang nghiêm, nhiều người thường đặt bàn tay phải lên ngực trái (phía trái tim) khi hát Quốc ca?', 'Để biểu thị tình yêu Tổ quốc thiêng liêng xuất phát từ sâu thẳm trái tim, nhịp đập trung thành và niềm tự hào dân tộc của mỗi công dân', ['Vì sợ gió thổi bay mất cúc áo ngực', 'Vì quy định kiểm tra nhịp tim trước khi học', 'Chỉ để cho đẹp đội hình chụp ảnh'],
               'Bàn tay đặt lên trái tim hòa nhịp Quốc ca là biểu tượng cảm xúc thiêng liêng đẹp đẽ của người yêu nước.', 'Ý nghĩa đặt tay lên ngực trái'),
            _q(1, 15, 'advanced', 'Ngoài việc đứng nghiêm hát Quốc ca thật hay vào sáng thứ Hai, lòng yêu Tổ quốc của một học sinh lớp 3 còn cần được chứng minh bằng hành động bền bỉ nào suốt cả tuần?', 'Chăm chỉ học tập tốt, vâng lời thầy cô cha mẹ, đoàn kết giúp bạn, giữ gìn môi trường xanh sạch và tôn trọng di tích lịch sử dân tộc', ['Chỉ đứng nghiêm 5 phút thứ Hai rồi cả tuần phá phách lười học', 'Chỉ mặc áo cờ đỏ sao vàng khi đi chụp ảnh', 'Không cần làm việc tốt nào hết'],
               'Yêu nước là hành động học tập và cống hiến tốt mỗi ngày chứ không chỉ dừng ở nghi thức!', 'Hành động yêu nước hằng ngày'),
        ]
    ))

    # BÀI 2: Ham học hỏi
    lessons.append(make_lesson(
        'daoduc3-c1', 'daoduc3-b02', 'Bài 2. Ham Học hỏi', 2,
        'Nhận biết biểu hiện của tinh thần ham học hỏi, tò mò khám phá tri thức đúng cách và biết cách rèn luyện thói quen học hỏi mỗi ngày',
        ['Ham học hỏi', 'Tò mò khám phá', 'Đọc sách và đặt câu hỏi'],
        [
            _q(2, 1, 'basic', 'Biểu hiện rõ nhất của một bạn học sinh lớp 3 có tinh thần HAM HỌC HỎI là gì?', 'Chăm chú nghe giảng, mạnh dạn đặt câu hỏi "Vì sao?" khi chưa hiểu, thích đọc sách khám phá kiến thức mới và học hỏi điểm hay từ bạn bè', ['Chỉ làm qua loa đúng phần bài tập bắt buộc rồi thôi', 'Giấu dốt không dám hỏi khi chưa hiểu bài', 'Cho rằng mình đã biết hết mọi thứ không cần học thêm'],
               'Trí tuệ phát triển mạnh mẽ nhất khi ta giữ được sự tò mò lành mạnh và niềm vui khám phá tri thức mỗi ngày.', 'Biểu hiện ham học hỏi',
               fig=table_fig('Thói quen Ham Học hỏi', ['Kênh học', 'Cách làm thông minh'], [['Trong lớp', 'Hỏi chỗ chưa rõ'], ['Thư viện', 'Đọc thêm sách hay'], ['Từ bạn bè', 'Học điều hay của bạn'], ['Thực tế', 'Quan sát thiên nhiên']])),
            _q(2, 2, 'basic', 'Khi cô giáo giảng xong một kiến thức mới trên lớp mà em vẫn còn một chi tiết chưa hiểu rõ, người ham học hỏi nên làm gì?', 'Giơ tay lễ phép xin phép cô giảng giải lại phần đó (hoặc hỏi lại cô vào giờ giải lao) đến khi hiểu tường tận mới thôi', ['Im lặng giả vờ gật đầu như đã hiểu hết vì sợ bạn cười', 'Bỏ luôn phần kiến thức đó không thèm quan tâm nữa', 'Chờ cuối năm học mới hỏi'],
               '"Hỏi một câu có thể ngại một phút, không hỏi thì dốt cả đời" – mạnh dạn hỏi khi chưa hiểu là phẩm chất tuyệt vời!', 'Mạnh dạn hỏi khi chưa rõ'),
            _q(2, 3, 'basic', 'Ngoài sách giáo khoa trên lớp, nguồn tri thức bổ ích và an toàn nào phù hợp nhất để học sinh lớp 3 mở rộng hiểu biết mỗi ngày?', 'Sách khoa học thiếu nhi, truyện lịch sử, bách khoa toàn thư tranh ảnh, bảo tàng và các chương trình giáo dục khoa học lành mạnh có người lớn đồng hành', ['Những video trò đùa nguy hiểm vô bổ trên mạng', 'Ngồi nghe tin đồn truyền miệng thiếu căn cứ', 'Chỉ đọc vỏ quảng cáo đồ ăn vặt'],
               'Sách là người thầy thông thái vĩ đại nhất mở ra cả thế giới tri thức bao la ngay trước mắt em!', 'Tìm nguồn tri thức lành mạnh'),
            _q(2, 4, 'basic', 'Khi thấy một bạn trong lớp có cách giải bài toán hay hơn hoặc vẽ tranh phối màu đẹp hơn mình, thái độ ham học hỏi đúng đắn là gì?', 'Vui vẻ khen ngợi bạn và khiêm tốn hỏi bạn chỉ cho mình bí quyết để cùng tiến bộ', ['Ghen tị bĩu môi bảo bạn chỉ gặp may', 'Lén giấu bài của bạn đi không cho ai xem', 'Không thèm học theo vì tự ái'],
               '"Học thầy không tày học bạn" – khiêm tốn học cái hay của bạn bè giúp em giỏi lên gấp bội!', 'Khiêm tốn học hỏi bạn bè'),
            _q(2, 5, 'basic', 'Nhà bác học vĩ đại như Bác Hồ, Ê-đi-xơn hay Lương Thế Vinh dù đã đạt nhiều thành tựu lớn nhưng suốt đời vẫn không ngừng đọc sách, học ngoại ngữ và tìm tòi. Điều đó dạy ta bài học gì?', 'Sự học là suốt đời không có điểm dừng; càng hiểu biết rộng ta càng thấy thế giới kì diệu và muốn học thêm mãi', ['Chỉ cần học giỏi ở tiểu học rồi nghỉ học luôn', 'Người thông minh bẩm sinh không cần đọc sách', 'Học xong lớp 3 là đã biết hết tri thức nhân loại'],
               'Bác Hồ luôn tự học suốt cuộc đời và là tấm gương sáng ngời nhất về tinh thần hiếu học!', 'Gương sáng ham học suốt đời'),
            _q(2, 6, 'basic', 'Tác hại của tâm lí "Tự mãn" (nghĩ mình điểm 10 rồi nên kiêu ngạo, lười đọc thêm, không chịu nghe góp ý) là gì?', 'Khiến kiến thức dậm chân tại chỗ, dễ chủ quan mắc lỗi sai ngớ ngẩn và nhanh chóng bị các bạn chăm chỉ vượt qua', ['Giúp mình mãi mãi giữ vững vị trí đứng đầu không cần nỗ lực', 'Giúp được thầy cô yêu quý hơn', 'Giúp mọi bài khó tự động dễ đi'],
               'Khiêm tốn và không ngừng nỗ lực giữ cho ngọn lửa tri thức luôn rực cháy!', 'Tránh tâm lí tự mãn'),
            _q(2, 7, 'application', 'Buổi sáng đi dạo vườn cùng bố, Lan thấy hạt đậu nảy mầm hướng ngọn lên phía ánh nắng mặt trời dù chậu đặt hơi nghiêng. Tò mò quá, Lan nên làm gì để thỏa mãn sự ham học hỏi khoa học?', 'Ghi chép lại câu hỏi vào sổ tay nhỏ, quan sát theo dõi thêm mấy ngày và cùng bố tìm đọc sách Tự nhiên hoặc hỏi cô giáo giải thích hiện tượng hướng sáng của cây', ['Nhổ tung cây đậu lên vứt đi cho đỡ thắc mắc', 'Bịa đại một câu chuyện thần tiên không đúng sự thật', 'Quên ngay lập tức không thèm suy nghĩ'],
               'Quan sát – Ghi chép – Đặt câu hỏi – Tìm kiểm chứng khoa học là quy trình chuẩn của nhà khoa học nhí!', 'Khám phá thế giới tự nhiên'),
            _q(2, 8, 'application', 'Ở thư viện trường có phát động phong trào "Đọc sách mở chân trời". Biểu đồ thống kê số quyển sách hay đã đọc trong học kì 1 của 4 bạn lớp 3A. Hỏi tổng số sách 4 bạn đã đọc và bạn nào đọc nhiều nhất?', 'Tổng 48 quyển; bạn Chi đọc nhiều nhất (15 quyển)', ['Tổng 40 quyển; bạn An nhiều nhất', 'Tổng 45 quyển; bạn Bình nhiều nhất', 'Tổng 52 quyển; bạn Dũng nhiều nhất'],
               '10 + 12 + 15 + 11 = 48 quyển sách; bạn Chi dẫn đầu 15 quyển cực kì đáng ngưỡng mộ!', 'Đọc biểu đồ phong trào đọc sách',
               fig=bars_fig('Số sách đọc trong học kì 1 (3A)', ['An', 'Bình', 'Chi', 'Dũng'], [10, 12, 15, 11], 'quyển')),
            _q(2, 9, 'application', 'Bạn Minh muốn học thêm cách gấp máy bay giấy bay xa và tìm hiểu về vũ trụ nhưng trên mạng Internet có quá nhiều thông tin lẫn lộn. Minh cần làm gì để học hỏi an toàn và chính xác?', 'Xin phép bố mẹ ngồi cùng tìm những kênh khoa học thiếu nhi uy tín, đọc sách thư viện hoặc hỏi trực tiếp thầy cô giáo tin cậy', ['Tự ý bấm vào mọi đường link quảng cáo lạ trên mạng', 'Tin ngay bất kì tin giật gân nào không cần kiểm chứng', 'Ngồi chơi điện thoại lén suốt 4 tiếng ban đêm'],
               'Có người lớn định hướng và kiểm chứng nguồn sách chuẩn giúp em học nhanh mà an toàn tuyệt đối.', 'Học hỏi an toàn trên mạng'),
            _q(2, 10, 'application', 'Một lần nhóm em được giao tìm hiểu về nghề làm gốm truyền thống ở địa phương. Thay vì chỉ chép vài dòng có sẵn, nhóm nên làm cách nào để học hỏi sâu sắc và thú vị nhất?', 'Chuẩn bị sẵn bộ câu hỏi gọn gàng, đến tham quan (có thầy cô hoặc bố mẹ đi cùng), quan sát nghệ nhân nặn gốm và lễ phép phỏng vấn ghi chép lại trải nghiệm thật', ['Chờ một bạn khác làm hết rồi chép y nguyên nộp cho xong', 'Không cần tìm hiểu, tự bịa ra quy trình nặn gốm', 'Đến nơi chỉ chạy nhảy nghịch đất sét phá đồ'],
               'Học qua trải nghiệm thực tế và đặt câu hỏi trực tiếp giúp kiến thức nhớ sâu và sống động vô cùng!', 'Học hỏi qua trải nghiệm thực tế'),
            _q(2, 11, 'application', 'Nếu một câu hỏi của em nêu lên trong giờ học làm một vài bạn cười vì nghĩ câu hỏi đó hơi ngây ngô, em có nên nản chí bỏ thói quen đặt câu hỏi không?', 'Không bao giờ nản chí! Mọi phát minh lớn đều bắt đầu từ những câu hỏi giản dị; cô giáo luôn trân trọng những học sinh dám suy nghĩ và đặt câu hỏi thẳng thắn', ['Có, từ nay im lặng không bao giờ phát biểu nữa', 'Đứng dậy cãi nhau với các bạn cười mình', 'Khóc òa bỏ chạy khỏi lớp'],
               'Sự dũng cảm đặt câu hỏi vượt qua ngại ngùng là chìa khóa của tư duy phản biện sắc bén!', 'Vượt qua ngại ngùng khi hỏi'),
            _q(2, 12, 'application', 'Bạn Hà tự lập một quyển "Sổ tay Điều em mới học": mỗi tối trước khi đi ngủ bạn ghi lại 1 điều hay mới khám phá được trong ngày. Việc làm này giúp ích gì cho Hà?', 'Giúp hệ thống hóa trí nhớ, biến kiến thức nghe thoáng qua thành hiểu biết bền vững của riêng mình và tạo niềm vui thấy bản thân tiến bộ từng ngày', ['Làm tốn giấy chẳng có ích lợi gì', 'Giúp Hà thức khuya hơn tới 12 giờ đêm', 'Chỉ để khoe cho đẹp bàn học'],
               'Viết lại điều mới học mỗi ngày là bí quyết ghi nhớ lâu dài của rất nhiều người thành công!', 'Thói quen Sổ tay Tri thức'),
            _q(2, 13, 'advanced', 'Bạn An đặt kế hoạch mỗi ngày đọc thêm 12 trang sách kiến thức ngoài giờ lên lớp. Trong 1 tuần lễ có 7 ngày (trong đó ngày Chủ nhật An đi thăm bà nên đọc ít hơn, chỉ đọc 8 trang, 6 ngày còn lại đọc đủ 12 trang/ngày). Hỏi cả tuần An đọc được tất cả bao nhiêu trang sách bổ ích?', '80 trang sách (12 x 6 + 8 = 80)', ['72 trang sách', '84 trang sách', '68 trang sách'],
               '6 ngày x 12 trang = 72 trang; cộng ngày Chủ nhật 8 trang = 80 trang sách đầy tri thức!', 'Kế hoạch đọc sách tuần'),
            _q(2, 14, 'advanced', 'Vì sao tục ngữ Việt Nam có câu: "Đi một ngày đàng, học một sàng khôn"?', 'Khuyên con người mạnh dạn mở rộng tầm mắt giao lưu, quan sát cuộc sống xung quanh và khiêm tốn học hỏi ở mọi nơi, mọi người để tích lũy vốn sống phong phú', ['Vì chỉ khi đi bộ ngoài đường mới được đi học', 'Vì mỗi ngày đi bộ sẽ nhặt được một cái sàng', 'Vì ngồi trong lớp không thể học được gì'],
               'Thế giới xung quanh là lớp học khổng lồ dành cho những đôi mắt biết quan sát và trái tim ham học hỏi.', 'Ý nghĩa câu tục ngữ Hiếu học'),
            _q(2, 15, 'advanced', 'Trong thời đại công nghệ phát triển nhanh chóng hiện nay, giữa "Học vẹt thuộc lòng để qua bài kiểm tra" và "Hiểu bản chất vấn đề, biết đặt câu hỏi và tự tìm tòi giải pháp", cách học nào giúp em thích nghi tốt nhất tương lai?', 'Cách học thứ hai: hiểu sâu bản chất, chủ động tư duy đặt câu hỏi và biết tự học suốt đời sẽ giúp em tự tin giải quyết mọi bài toán mới mẻ trong tương lai', ['Cách học vẹt: không cần hiểu chỉ cần chép nhanh', 'Không cần học cách nào cả vì máy tính làm hết rồi', 'Chỉ học duy nhất 1 môn bỏ các môn khác'],
               'Khả năng tự học và ham học hỏi suốt đời là kĩ năng vàng của công dân thế kỉ 21!', 'Tư duy học tập hiện đại'),
        ]
    ))

    # BÀI 3: Tích cực hoàn thành nhiệm vụ ở nhà và ở trường
    lessons.append(make_lesson(
        'daoduc3-c1', 'daoduc3-b03', 'Bài 3. Tích cực Hoàn thành Nhiệm vụ ở Nhà và ở Trường', 3,
        'Biết nhận diện trách nhiệm của bản thân tại gia đình và lớp học; chủ động, kiên trì hoàn thành tốt công việc được giao mà không ỷ lại',
        ['Hoàn thành nhiệm vụ', 'Trách nhiệm ở nhà ở trường', 'Kiên trì vượt khó'],
        [
            _q(3, 1, 'basic', 'Những nhiệm vụ chính của học sinh lớp 3 tại GIA ĐÌNH và tại TRƯỜNG HỌC là gì?', 'Ở nhà: tự học, giữ gọn góc học và làm việc vừa sức; Ở trường: học chăm, trực nhật sạch và tham gia việc tập thể đúng phân công', ['Ở nhà chỉ chơi điện tử; ở trường chỉ chạy nhảy', 'Đợi ông bà cha mẹ làm hộ mọi việc cá nhân', 'Chỉ làm việc nào được thưởng tiền ngay'],
               'Nhận rõ vai trò của mình ở cả hai môi trường giúp em sống có trách nhiệm và tự lập vững vàng.', 'Nhiệm vụ của học sinh lớp 3',
               fig=table_fig('Nhiệm vụ của Em Lớp 3', ['Môi trường', 'Việc hoàn thành tốt'], [['Ở nhà', 'Gọn góc học, phụ mẹ'], ['Ở lớp học', 'Học bài, làm bài đủ'], ['Việc tổ lớp', 'Trực nhật, kê bàn'], ['Khi gặp khó', 'Kiên trì, nhờ gợi ý']])),
            _q(3, 2, 'basic', 'Thái độ nào thể hiện sự "TÍCH CỰC hoàn thành nhiệm vụ" chứ không phải làm đối phó cho xong?', 'Chủ động bắt tay làm sớm đúng hạn, làm cẩn thận chu đáo hết sức mình và kiểm tra lại kết quả trước khi báo cáo', ['Chờ tới phút cuối cùng sát giờ nộp mới làm ẩu cho có', 'Làm qua loa nửa vời rồi bỏ dở giữa chừng', 'Phải đợi bố mẹ hoặc lớp trưởng nhắc năm lần mới làm'],
               'Chủ động, cẩn thận và dứt điểm từ đầu tới cuối làm nên chất lượng công việc vượt trội!', 'Thái độ tích cực làm việc'),
            _q(3, 3, 'basic', 'Khi được cô giáo phân công phụ trách việc chăm sóc cây xanh ở cửa sổ lớp trong tuần, việc hoàn thành tốt nhiệm vụ đòi hỏi em làm gì?', 'Chủ động kiểm tra tưới lượng nước vừa đủ mỗi ngày, nhặt lá úa gọn gàng và báo cô nếu cây bị sâu héo', ['Ngày đầu tưới ngập úng rồi bốn ngày sau quên bẵng luôn', 'Nhờ bạn khác làm hết suốt tuần còn mình đi chơi', 'Đổ mực thừa vào chậu cây'],
               'Kiên trì thực hiện đều đặn nhiệm vụ được tin tưởng giao phó rèn cho em chữ Tín rất lớn.', 'Trách nhiệm với nhiệm vụ giao'),
            _q(3, 4, 'basic', 'Việc nhà nào dưới đây hoàn toàn VỪA SỨC và giúp rèn luyện tính tự lập tuyệt vời cho bạn nhỏ lớp 3?', 'Quét nhà lau bàn ăn, gấp quần áo sạch xếp tủ, nhặt rau phụ mẹ, trông em nhỏ an toàn và rửa cốc chén nhẹ không vỡ', ['Trèo lên mái nhà sửa ăng-ten tivi', 'Tự lái xe máy đi chợ giúp mẹ', 'Khuân vác bình ga nặng một mình'],
               'Làm đều đặn các việc nhà vừa sức mỗi ngày giúp gia đình đầm ấm và rèn đôi tay khéo léo.', 'Việc nhà vừa sức lớp 3'),
            _q(3, 5, 'basic', 'Nếu đang làm một nhiệm vụ được giao (như giải bài tập khó hay vẽ áp phích nhóm) mà gặp trở ngại hơi mệt hoặc hơi khó, em nên làm gì?', 'Bình tĩnh nghỉ chút lấy lại tinh thần, tìm cách tháo gỡ từng bước hoặc hỏi gợi ý thầy cô bố mẹ để kiên trì làm trọn vẹn đến cùng', ['Vứt bỏ luôn không làm nữa cho đỡ mệt', 'Đổ thừa nhiệm vụ này vô lí không ai làm được', 'Lấy bài của bạn khác nộp thay'],
               'Không bỏ cuộc giữa chừng khi gặp chút khó khăn là dấu hiệu của người có ý chí mạnh mẽ!', 'Kiên trì hoàn thành tới cùng'),
            _q(3, 6, 'basic', 'Khi thấy mình hoàn thành xong sớm nhiệm vụ cá nhân tại lớp (ví dụ trực nhật xong bàn của tổ mình), em có thể làm thêm hành động đẹp nào?', 'Chủ động hỏi xem các bạn trong tổ hay cô giáo có cần phụ thêm việc gì nhẹ nhàng không để giúp tập thể cùng hoàn thành nhanh', ['Ngồi vỗ tay cười chế giễu tổ khác làm chậm', 'Bày rác lại ra góc tổ bên cạnh', 'Chạy ra ngoài hành lang la hét'],
               'Tinh thần đồng đội hỗ trợ nhau sau khi xong phần mình làm tập thể lớp gắn kết tuyệt vời.', 'Tinh thần đồng đội tập thể'),
            _q(3, 7, 'application', 'Bạn Minh hứa giúp mẹ mỗi chiều đi học về lúc 17 giờ 00 sẽ cho chú mèo ăn và thu dọn quần áo khô trên dây phơi tầng 1. Hôm nay vừa 17 giờ (như đồng hồ) thì bạn hàng xóm sang rủ đi đá bóng ngay. Minh nên sắp xếp thế nào?', 'Nói bạn chờ khoảng 10 phút để mình hoàn thành dứt điểm việc cho mèo ăn và thu gấp quần áo gọn gàng cho mẹ yên tâm trước rồi mới ra sân đá bóng vui vẻ', ['Bỏ mặc quần áo ngoài trời sắp mưa để chạy đi đá bóng luôn', 'Bảo mẹ tự đi làm đi con bận chơi rồi', 'Ném đại quần áo xuống ghế salon chưa gấp rồi chạy đi'],
               '"Xong việc mới đi chơi" là nguyên tắc quản lí bản thân cực kì trưởng thành của học sinh lớp 3!', 'Ưu tiên hoàn thành việc nhà',
               fig=fig_clock(5, 0, '17 giờ chiều: Giờ làm việc nhà giúp mẹ')),
            _q(3, 8, 'application', 'Trong dự án nhóm môn Tự nhiên và Xã hội, 4 bạn lớp 3B phân công: An tìm tranh, Bình viết chữ đẹp, Chi trang trí viền, Dũng chuẩn bị bìa cứng và thuyết trình. Đến sát ngày nộp, Dũng mải chơi chưa chuẩn bị bài thuyết trình làm cả nhóm lo lắng. Em góp ý Dũng thế nào?', 'Nhắc Dũng thấy trách nhiệm chung ảnh hưởng cả nhóm, cùng nhau tóm tắt 3 ý chính để Dũng kịp tập nói trôi chảy và rút kinh nghiệm sau', ['Cả nhóm loại tên Dũng ra khỏi bài và đánh bạn', 'Xé luôn tấm bìa cứng không nộp bài cho cô giáo', 'Im lặng để mặc Dũng đứng lên bục giảng ấp úng không nói được'],
               'Một mắt xích chậm trễ ảnh hưởng cả tập thể; nhắc nhở trách nhiệm đi đôi với hỗ trợ kịp thời giữ thành công chung.', 'Trách nhiệm trong làm việc nhóm'),
            _q(3, 9, 'application', 'Cô giáo tổng kết phong trào "Tuần lễ Tích cực Hoàn thành Nhiệm vụ" của lớp 3C (biểu đồ dưới đây ghi nhận số nhiệm vụ đúng hạn của 4 tổ trong tuần). Tổ nào hoàn thành xuất sắc nhiều nhất và hơn tổ thấp nhất mấy nhiệm vụ?', 'Tổ 4 cao nhất (24 nhiệm vụ), nhiều hơn Tổ 2 (18 nhiệm vụ) đúng 6 nhiệm vụ', ['Tổ 1 cao nhất; hơn 4 nhiệm vụ', 'Tổ 3 cao nhất; hơn 5 nhiệm vụ', 'Tổ 4 cao nhất; hơn 8 nhiệm vụ'],
               '24 - 18 = 6 nhiệm vụ; Tổ 4 là lá cờ đầu tích cực của cả lớp!', 'Đọc biểu đồ thi đua 4 tổ',
               fig=bars_fig('Nhiệm vụ hoàn thành đúng hạn (3C)', ['Tổ 1', 'Tổ 2', 'Tổ 3', 'Tổ 4'], [20, 18, 22, 24], 'việc')),
            _q(3, 10, 'application', 'Buổi tối em làm bài tập Tiếng Việt thấy còn 1 câu đặt câu hỏi hơi khó chưa nghĩ ra. Ngoài ra bố còn dặn lau sạch chiếc bàn ăn sau bữa tối. Em giải quyết cả hai việc thế nào cho khoa học?', 'Nhanh nhẹn lau sạch bàn ăn sau bữa tối phụ bố mẹ trước, rồi rửa tay sạch ngồi tập trung đọc kĩ đề Tiếng Việt suy nghĩ tìm lời giải', ['Bỏ luôn việc lau bàn ăn lẫn câu hỏi khó đi ngủ sớm', 'Vừa cầm giẻ lau ướt vừa viết vở Tiếng Việt', 'Chờ sáng mai đến lớp mượn vở bạn chép'],
               'Sắp xếp trình tự gọn gàng việc nhà – việc học giúp mọi nhiệm vụ đều hoàn thành nhẹ tênh!', 'Sắp xếp việc nhà và việc học'),
            _q(3, 11, 'application', 'Nếu em được bầu làm Tổ trưởng trong 1 tháng và cô giáo giao nhiệm vụ theo dõi sổ trực nhật, nhắc các bạn xếp hàng ngay ngắn nhưng có một bạn thân trong tổ lại đi muộn trốn trực nhật. Em làm gì cho công bằng?', 'Nhắc nhở bạn thân nhẹ nhàng nhưng kiên quyết thực hiện bù phần trực nhật và ghi nhận trung thực tình hình tổ, không vì bạn thân mà bao che bỏ qua lỗi', ['Bao che ghi bạn ấy làm rất tốt để lấy lòng bạn', 'Làm thay hết phần bạn suốt cả tháng để che giấu', 'Mắng chửi bạn trước toàn trường'],
               'Công tâm không thiên vị ngay cả với bạn thân thể hiện bản lĩnh người cán bộ lớp gương mẫu!', 'Công tâm khi làm nhiệm vụ quản lí'),
            _q(3, 12, 'application', 'Sau khi làm xong nhiệm vụ được giao (như rửa bát nhựa phụ mẹ hay kê lại bàn ghế lớp), bước kiểm tra cuối cùng nào giúp chất lượng công việc đạt điểm 10 hoàn hảo?', 'Nhìn bao quát kiểm tra lại một lượt xem còn sót bọt xà phòng, còn rác rơi hay bàn ghế còn xô lệch không để chỉnh sửa ngay trước khi kết thúc', ['Làm xong cái đầu tiên là chạy biến đi luôn không cần nhìn lại', 'Khoe ầm ĩ rồi để bừa bãi dụng cụ lau dọn giữa sàn', 'Chờ người khác đi dọn lại giúp mình'],
               'Thói quen tự kiểm tra lại (Self-check) giúp mọi sản phẩm học tập và lao động của em luôn đạt chuẩn cao!', 'Tự kiểm tra kết quả công việc'),
            _q(3, 13, 'advanced', 'Một tổ trực nhật gồm 4 bạn cần sắp xếp 16 bộ bàn ghế thẳng hàng và lau sạch 2 chiếc bảng phụ cùng 1 bảng chính. Nếu 4 bạn chia đều công việc (mỗi bạn chỉnh 4 bộ bàn ghế hết 2 phút, thêm 1 bạn lau bảng chính 3 phút, 2 bạn lau bảng phụ mỗi người 2 phút và bạn thứ 4 quét sàn 4 phút) và làm song song cùng lúc. Hỏi tối đa sau bao nhiêu phút cả tổ xong hoàn toàn?', '6 phút (2 phút chỉnh bàn + 4 phút dài nhất của việc quét sàn)', ['2 phút', '15 phút', '10 phút'],
               'Chỉnh bàn đồng loạt mất 2 phút; tiếp theo 4 việc kia làm song song mất tối đa theo bạn quét sàn 4 phút -> Tổng 2 + 4 = 6 phút! Làm việc có kế hoạch phối hợp cực kì nhanh!', 'Tối ưu phối hợp nhóm'),
            _q(3, 14, 'advanced', 'Vì sao rèn luyện thói quen tích cực hoàn thành nhiệm vụ từ tuổi lớp 3 lại trở thành nền tảng thành công khi trưởng thành?', 'Vì người chủ động chịu trách nhiệm, không trì hoãn và kiên trì làm trọn vẹn luôn tạo uy tín lớn, được tin tưởng giao trọng trách', ['Vì lớn lên không còn ai giao nhiệm vụ nữa', 'Vì chỉ cần làm việc chăm chỉ ở lớp 3 là đủ cho cả đời', 'Vì người lười biếng luôn may mắn hơn'],
               'Kỉ luật tự thân và tinh thần trách nhiệm là vốn quý đồng hành cùng em suốt chặng đường lớn khôn.', 'Giá trị lâu dài của tinh thần trách nhiệm'),
            _q(3, 15, 'advanced', 'Giữa "Làm nhanh ẩu cho xong để mau đi chơi" và "Làm cẩn thận đúng hạn rồi mới nghỉ ngơi thoải mái", sự khác biệt lâu dài về năng lực là gì?', 'Người làm ẩu dễ sai sót mất uy tín và tốn công làm lại; người làm cẩn thận đúng hạn rèn tư duy chuẩn và sống thảnh thơi hơn', ['Người làm ẩu luôn giỏi hơn vì thừa nhiều thời gian', 'Không có sự khác biệt nào cả', 'Làm cẩn thận lúc nào cũng bị muộn giờ'],
               '"Chất lượng làm nên thương hiệu cá nhân" – cẩn thận từng việc nhỏ tạo nên phong thái tuyệt vời!', 'Chất lượng công việc'),
        ]
    ))

    # BÀI 4: Giữ lời hứa và trung thực trong học tập
    lessons.append(make_lesson(
        'daoduc3-c2', 'daoduc3-b04', 'Bài 4. Giữ Lời hứa và Trung thực trong Học tập', 4,
        'Nâng cao ý thức trung thực tuyệt đối trong học tập, kiểm tra, thi cử và giữ vững chữ tín trong lời hứa học tập với thầy cô, gia đình',
        ['Trung thực trong học tập', 'Không gian lận thi cử', 'Giữ chữ tín học đường'],
        [
            _q(4, 1, 'basic', 'Biểu hiện ĐÚNG ĐẮN của đức tính TRUNG THỰC trong học tập đối với học sinh lớp 3 là gì?', 'Tự lực suy nghĩ làm bài tập và bài kiểm tra bằng chính kiến thức của mình, không nhìn bài bạn, không dùng tài liệu lén lút và báo đúng điểm số thật với gia đình', ['Chép nguyên văn bài làm của bạn ngồi cạnh khi cô giáo quay đi', 'Sửa điểm thấp trên bài kiểm tra thành điểm cao trước khi đưa bố mẹ kí', 'Nhờ anh chị lớp lớn giải hộ hết rồi nhận là mình tự nghĩ'],
               'Điểm 8 tự làm bằng thực lực của em đáng tự hào gấp trăm lần điểm 10 gian lận!', 'Khái niệm Trung thực học tập',
               fig=table_fig('Học tập Trung thực Lớp 3', ['Hoạt động', 'Hành vi chuẩn mực'], [['Giờ kiểm tra', 'Tự làm, che bài kín'], ['Chấm chữa bài', 'Báo đúng lỗi sai'], ['Báo kết quả nhà', 'Đưa đúng điểm chấm'], ['Bài tập nhóm', 'Đóng góp rõ ràng']])),
            _q(4, 2, 'basic', 'Khi cô giáo trả bài kiểm tra định kì và nhận thấy cô vô tình cộng nhầm DƯ cho em thêm 1 điểm (lẽ ra 8 điểm nhưng cô cộng thành 9 điểm), hành động trung thực cao đẹp nhất là gì?', 'Lễ phép mang bài lên thưa rõ với cô giáo để cô cộng sửa lại đúng số điểm 8 thực tế của bài làm', ['Im lặng cất nhanh vào cặp khoe với bố mẹ là được 9 điểm', 'Gạch xóa phần lỗi sai đi cho giống 9 điểm thật', 'Chạy ra khoe trêu bạn đạt 8 điểm'],
               'Trung thực ngay cả khi việc nói thật làm điểm số ghi trên giấy giảm đi 1 điểm chứng tỏ nhân cách cực kì đáng nể!', 'Trung thực khi chấm nhầm thừa điểm'),
            _q(4, 3, 'basic', 'Vì sao trong giờ kiểm tra viết hoặc thi học kì, cô giáo luôn nhắc các bạn ngồi ngay ngắn và không quay sang nhìn bài hay hỏi bài nhau?', 'Để đánh giá chính xác thực lực hiểu bài của từng bạn, giúp thầy cô và bố mẹ biết chỗ nào em cần bồi dưỡng thêm đồng thời rèn nhân cách trung thực', ['Vì cô giáo không muốn các bạn nói chuyện cười vui', 'Vì kiến thức giống nhau không cần kiểm tra', 'Để làm khó học sinh chơi'],
               'Kiểm tra là "chiếc gương soi" phản chiếu đúng trình độ hiện tại để em biết đường cố gắng học tốt hơn!', 'Mục đích của kiểm tra trung thực'),
            _q(4, 4, 'basic', 'Nếu em vô tình bị điểm chưa cao ở một bài kiểm tra môn Tiếng Anh hay Toán, hành động trung thực và có trách nhiệm với bố mẹ là gì?', 'Đưa nguyên bài kiểm tra cho bố mẹ xem, nói thật lí do mình còn hổng kiến thức phần nào và lập kế hoạch ôn tập kĩ hơn cho bài sau', ['Giấu bài kiểm tra vào gầm giường hoặc vứt thùng rác', 'Giả chữ kí của bố mẹ kí vào tờ bài kiểm tra', 'Nói dối là cả lớp đều làm bài kém và cô chưa trả bài'],
               'Nói thật kết quả chưa tốt với cha mẹ sẽ nhận được sự đồng hành giúp đỡ đúng lúc thay vì nỗi lo bị phát hiện dối trá.', 'Trung thực báo điểm gia đình'),
            _q(4, 5, 'basic', 'Bạn thân ngồi cùng bàn thì thầm xin em cho chép đáp án 2 câu cuối bài kiểm tra 15 phút vì tối qua bạn ấy mải chơi quên ôn bài. Em nên ứng xử thế nào?', 'Nhẹ nhàng ra hiệu từ chối che bài lại giữ kỉ luật phòng thi; hết giờ kiểm tra sẽ tận tình giảng lại 2 câu đó cho bạn hiểu cặn kẽ để thi cuối kì bạn tự làm tốt', ['Mở rộng tờ giấy cho bạn chép hết cả bài mới là bạn tốt', 'Viết sẵn đáp án ra mẩu giấy nhỏ ném sang bàn bạn', 'Đứng dậy mách thật to giữa giờ kiểm tra làm bạn hoảng loạn'],
               'Không tiếp tay cho gian lận thi cử nhưng sẵn lòng dạy bạn hiểu bài sau giờ học mới là tình bạn chân chính!', 'Từ chối cho chép bài khéo léo'),
            _q(4, 6, 'basic', 'Khi em đã tự hứa với cô giáo và bố mẹ: "Học kì này con sẽ tự giác ôn tập đều đặn không chép bài mẫu có sẵn nữa!", việc giữ trọn lời hứa đó mang lại giá trị gì cho em?', 'Kiến thức nền tảng vững chắc thật sự, tư duy tự lập sắc bén và sự tin tưởng tuyệt đối từ gia đình thầy cô', ['Làm điểm số giảm sút mãi mãi', 'Mất hết thời gian giải trí', 'Không ai quan tâm tới lời hứa học tập'],
               'Chữ tín gắn liền với sự trung thực tự lập là tài sản quý giá nhất của người học trò.', 'Giá trị giữ lời hứa học tập'),
            _q(4, 7, 'application', 'Bạn Minh lỡ quên học thuộc đoạn thơ ngắn ở nhà. Đến giờ kiểm tra miệng buổi sáng, Minh định mở hé quyển sách dưới ngăn bàn liếc đọc trộm khi cô gọi bạn khác. Nếu ngồi cạnh Minh, em nên khuyên bạn thế nào trong 1 phút trước giờ học?', 'Khuyên Minh cất ngay sách, nhẩm nhanh câu đã nhớ và nếu còn quên thì thẳng thắn xin lỗi cô xin nợ lại cuối giờ đọc bù trung thực', ['Canh chừng giúp Minh mở sách dưới gầm bàn khi cô quay lưng', 'Khen Minh thông minh nghĩ ra mẹo quay cóp hay quá', 'Cười lớn mách cả lớp trước khi vào tiết'],
               'Ngăn bạn kịp thời khỏi sai lầm quay cóp giữ cho bạn sự trong sáng ngay từ những tình huống nhỏ!', 'Ngăn bạn quay cóp kịp thời'),
            _q(4, 8, 'application', 'Cô giáo giao bài tập về nhà tìm hiểu về một loài cây và viết đoạn văn ngắn tự cảm nhận bằng lời văn của mình. Bạn Lan lên mạng chép nguyên văn 1 bài văn mẫu dài của người khác mà chẳng hiểu nghĩa vài từ khó trong đó. Điều này có hại gì cho Lan?', 'Lan không rèn được kĩ năng viết câu diễn đạt cảm xúc thật của bản thân, dễ bị lộ khi cô hỏi nghĩa từ và mất cơ hội phát triển tư duy sáng tạo riêng', ['Giúp Lan trở thành nhà văn nổi tiếng ngay lập tức', 'Không có hại gì vì văn mẫu luôn hay hơn mình tự viết', 'Giúp tiết kiệm giấy vở'],
               'Tham khảo ý hay là tốt, nhưng sao chép nguyên xi bài văn mẫu đánh mất giọng văn chân thật quý giá của em!', 'Tránh sao chép văn mẫu'),
            _q(4, 9, 'application', 'Trong đợt đánh giá phong trào "Lớp 3 Trung thực – Nói không với Quay cóp", 4 lớp khối 3 cùng kí cam kết thực hiện chuẩn mực kiểm tra nghiêm túc. Biểu đồ cho thấy số lượt nhắc nhở nhìn bài giảm mạnh qua 4 tháng ở khối 3. Từ Tháng 9 đến Tháng 12 số lượt vi phạm đã giảm bao nhiêu lượt?', 'Giảm 22 lượt (từ 25 lượt xuống chỉ còn 3 lượt)', ['Giảm 15 lượt', 'Giảm 20 lượt', 'Giảm 18 lượt'],
               '25 - 3 = 22 lượt giảm mạnh – ý thức tự giác và lòng tự trọng học đường ngày càng tỏa sáng!', 'Đọc biểu đồ trung thực thi cử',
               fig=bars_fig('Lượt nhắc nhở nhìn bài khối 3', ['Tháng 9', 'Tháng 10', 'Tháng 11', 'Tháng 12'], [25, 16, 8, 3], 'lượt')),
            _q(4, 10, 'application', 'Một bạn học sinh chép bài giải Toán trên sách giải về nộp đủ cho cô giáo nên cô khen bài sạch đúng hết. Nhưng hôm sau gọi lên bảng làm lại y hệt bài đó thì bạn ấy đứng ngây ra không giải được bước nào. Bài học rút ra là gì?', 'Dối trá trong học tập luôn tự lộ rõ khi đối diện thử thách thật; chỉ có tự mình suy nghĩ giải bài (dù sai rồi sửa lại) mới tạo ra năng lực thật sự', ['Do bảng lớp trơn khó viết hơn vở ở nhà', 'Nên chép đáp án vào lòng bàn tay trước khi lên bảng', 'Học thuộc lòng đáp số cuối mà không cần biết cách tính'],
               'Năng lực thật sự không bao giờ có được bằng con đường sao chép đối phó!', 'Bài học từ việc chép sách giải'),
            _q(4, 11, 'application', 'Bạn Hùng hứa với bạn Tú: "Tối nay tớ giải xong phần bài tập nhóm sẽ gửi kết quả để sáng mai hai đứa cùng ghép hoàn chỉnh nhé!". Tuy nhiên tối đó Hùng gặp bài khó làm chưa ra xong mà cứ ngại không dám nhắn báo. Hùng nên làm gì lúc 8 giờ tối?', 'Chủ động nhờ bố mẹ nhắn báo thật cho Tú phần đã xong và phần còn vướng để sáng mai hai bạn cùng gỡ ở lớp không lỡ việc chung', ['Tắt máy im lặng sáng mai lên lớp mới bảo chưa làm gì cả', 'Chép bừa đáp án sai nộp qua loa để cho xong lời hứa', 'Đổ tại mất điện cả khu phố'],
               'Trung thực giao tiếp khi gặp khó khăn giữ vững chữ tín trong hợp tác nhóm.', 'Trung thực trong hẹn việc nhóm'),
            _q(4, 12, 'application', 'Khi thầy cô cho học sinh tự chấm chéo vở bài tập hoặc tự chấm bài đọc của chính mình theo đáp án chuẩn trên bảng, thái độ trung thực đòi hỏi em chấm thế nào?', 'Soát cẩn thận từng câu đúng/sai theo đúng đáp án chuẩn của cô: câu nào sai thì đánh dấu nhẹ và viết đáp án đúng bên cạnh bằng bút chì để tự rút kinh nghiệm sâu', ['Tự chấm đúng hết 100% dù mình làm sai mất 3 câu', 'Chấm thật khắt khe trừ điểm vô lí cho bạn mình ghét', 'Sửa nhanh đáp án trong vở rồi mới chấm đúng'],
               'Tự chấm đúng lỗi sai giúp bộ não ghi nhớ lâu gấp đôi chỗ cần khắc phục!', 'Trung thực khi tự chấm bài'),
            _q(4, 13, 'advanced', 'Trong lớp 3A có 36 học sinh tham gia bài khảo sát trung thực: ở lần kiểm tra đầu tháng, có 30 bạn tự làm 100% bài không hỏi bạn; 6 bạn còn lại hơi lúng túng định quay hỏi nhưng đã kịp dừng lại tự làm nốt sau khi cô nhắc. Hỏi cuối buổi đó toàn bộ bao nhiêu bạn đã hoàn thành bài bằng chính sức mình?', 'Cả 36 học sinh đều tự hoàn thành bài kiểm tra bằng chính sức mình!', ['30 học sinh', '6 học sinh', '24 học sinh'],
               '30 bạn chủ động ngay từ đầu + 6 bạn kịp điều chỉnh tự làm = tất cả 36 bạn đều giữ trọn sự trung thực!', 'Giá trị tự điều chỉnh'),
            _q(4, 14, 'advanced', 'Vì sao danh nhân thế giới từng khẳng định: "Thà trượt một kì thi còn hơn gian lận để đỗ; vì một bài thi trượt có thể học lại để đỗ, nhưng nhân cách đã quen gian dối sẽ đánh mất lòng tự trọng suốt đời"?', 'Vì kiến thức thiếu có thể học bổ sung ngay, nhưng thói quen dối trá sẽ tạo nhân cách thiếu trung thực gây hại lâu dài', ['Vì thi trượt không bao giờ cần phải thi lại nữa', 'Vì gian lận luôn giúp ta có kiến thức thật', 'Vì nhân cách không quan trọng bằng điểm số giấy'],
               'Đặt nhân cách trung thực lên trên điểm số ảo là nền tảng giáo dục tử tế bền vững nhất!', 'Giá trị nhân cách hơn điểm số'),
            _q(4, 15, 'advanced', 'Giữa "Lời khen thật lòng dành cho sự tiến bộ 1 điểm (từ 6 lên 7 điểm)" và "Điểm 10 đi mượn bằng cách nhìn bài bạn", điều nào mang lại niềm hạnh phúc tự hào thực sự bên trong trái tim em?', 'Sự tiến bộ thật từ 6 lên 7 điểm bằng mồ hôi cố gắng của chính mình – vì em cảm nhận rõ mình thực sự trưởng thành mạnh mẽ và xứng đáng với lời khen!', ['Điểm 10 nhìn trộm bạn vì nhìn tờ giấy đẹp hơn', 'Cả hai đều mang lại cảm giác bất an giống nhau', 'Không cần cố gắng học tập làm gì'],
               'Niềm vui tự hào chân chính chỉ nảy nở từ những thành quả do chính đôi tay và trí óc em làm nên!', 'Niềm tự hào từ thực lực'),
        ]
    ))

    # BÀI 5: Quan tâm hàng xóm, láng giềng
    lessons.append(make_lesson(
        'daoduc3-c2', 'daoduc3-b05', 'Bài 5. Quan tâm Hàng xóm, Láng giềng', 5,
        'Nhận biết ý nghĩa của tình làng nghĩa xóm gắn bó và thực hành cách giao tiếp lễ phép, giữ trật tự chung và giúp đỡ hàng xóm vừa sức',
        ['Tình làng nghĩa xóm', 'Giữ trật tự khu dân cư', 'Giúp đỡ láng giềng'],
        [
            _q(5, 1, 'basic', 'Những hành động thân thiện lễ phép nào thể hiện sự quan tâm tốt đẹp đối với hàng xóm, láng giềng xung quanh nhà mình?', 'Chào hỏi lễ phép khi gặp gỡ, hỏi thăm khi bác hàng xóm ốm mệt, giữ trật tự giờ nghỉ ngơi và giúp đỡ những việc nhỏ vừa sức', ['Mở loa hát karaoke thật to lúc 11 giờ đêm', 'Quét rác nhà mình đẩy sang trước cổng nhà bên cạnh', 'Đá bóng mạnh vào cửa kính nhà hàng xóm'],
               '"Bán anh em xa, mua láng giềng gần" – những người sống cạnh ta mỗi ngày là chỗ dựa ấm áp nhất lúc cần.', 'Ứng xử đẹp với hàng xóm',
               fig=table_fig('Tình làng Nghĩa xóm', ['Hoàn cảnh', 'Cách cư xử văn minh'], [['Gặp ở ngõ, cầu thang', 'Mỉm cười, khoanh tay'], ['Giờ nghỉ trưa và tối', 'Nói khẽ, giảm tivi'], ['Bác hàng xóm yếu', 'Nhường lối, xách đồ'], ['Ngõ xóm chung', 'Không lấn, xả rác']])),
            _q(5, 2, 'basic', 'Ở khu chung cư hoặc ngõ xóm đông dân cư, khung giờ nào em và gia đình cần đặc biệt giữ yên lặng để tôn trọng giấc ngủ nghỉ ngơi của hàng xóm?', 'Giờ nghỉ trưa (khoảng 12g–13g30) và buổi tối muộn (sau 21g30–22g đêm đến sáng sớm)', ['Chỉ cần giữ yên lặng lúc 9 giờ sáng', 'Không cần giữ yên lặng vào bất kì giờ nào', 'Chỉ giữ yên lặng vào ngày thứ Hai'],
               'Giữ yên tĩnh vào giờ nghỉ trưa và ban đêm giúp người già, trẻ nhỏ và người đi làm quanh ta được hồi phục sức khỏe.', 'Tôn trọng giờ nghỉ chung'),
            _q(5, 3, 'basic', 'Khi đi trong thang máy chung cư hoặc đi ngang hành lang hẹp cùng bác hàng xóm lớn tuổi hay cô đang bế em bé, em cần cư xử thế nào?', 'Lễ phép chào hỏi, bấm giữ nút mở thang máy nhường người lớn tuổi và phụ nữ bế em bé bước vào/ra trước an toàn', ['Chen xô đẩy chạy vào trước chiếm chỗ bấm loạn các nút tầng', 'Đóng sập cửa thang máy ngay trước mặt bác hàng xóm', 'Chạy nhảy rung lắc trong thang máy'],
               'Nhường nhịn và giữ nút cửa thang máy cho hàng xóm là nét đẹp văn minh đô thị hiện đại!', 'Văn minh đi thang máy'),
            _q(5, 4, 'basic', 'Nếu nhà bác hàng xóm có việc bận đi vắng nhờ gia đình em nhận giúp một gói bưu phẩm hoặc trông chừng cổng hộ, khi bác về em nên làm gì?', 'Cất giữ gói hàng cẩn thận nguyên vẹn ở nơi khô ráo và lễ phép dùng hai tay trao lại tận tay bác ngay khi bác về', ['Tò mò tự ý bóc hộp hàng của bác ra xem bên trong có gì', 'Vứt gói hàng ngoài mưa ướt hết', 'Giữ luôn gói hàng quên không trả'],
               'Giữ gìn cẩn thận đồ gửi gắm chứng tỏ lòng tin cậy tuyệt đối giữa các gia đình láng giềng.', 'Giữ đồ hộ hàng xóm'),
            _q(5, 5, 'basic', 'Những việc làm nào sau đây dễ gây MẤT ĐOÀN KẾT hàng xóm láng giềng cần tránh tuyệt đối?', 'Vứt rác bừa bãi trước cửa nhà hàng xóm, để thú cưng phóng uế ra ngõ chung không dọn, hái trộm quả vườn nhà bên hoặc nói xấu sau lưng', ['Chia sẻ đĩa bánh ngon mới nấu tặng nhà bên cạnh', 'Cùng dọn vệ sinh con ngõ chung ngày cuối tuần', 'Tưới hộ chậu hoa khi hàng xóm đi du lịch vắng'],
               'Giữ vệ sinh chung và tôn trọng không gian riêng tư của nhà kế bên giữ ngõ xóm luôn êm ấm.', 'Tránh việc gây mất hòa khí'),
            _q(5, 6, 'basic', 'Vì sao ông cha ta dạy câu tục ngữ: "Hàng xóm tối lửa tắt đèn có nhau"?', 'Vì khi gặp hoạn nạn bất ngờ (ốm đau nửa đêm, mất điện, sự cố khẩn cấp), hàng xóm bên cạnh là người có mặt giúp đỡ ta nhanh kịp thời nhất', ['Vì nhà hàng xóm thường hay bị tắt đèn giống nhà mình', 'Vì phải mượn bật lửa của hàng xóm mỗi tối', 'Vì người thân ở xa không bao giờ quý bằng hàng xóm'],
               'Tình láng giềng gắn bó biến cả khu phố, thôn xóm thành một đại gia đình bình yên và an toàn.', 'Ý nghĩa câu tục ngữ láng giềng'),
            _q(5, 7, 'application', 'Cuối tuần nhà em có khách vui nên một vài bạn nhỏ rủ nhau chơi nhảy dây hò reo ầm ĩ ngay trước cửa phòng căn hộ của bà cụ hàng xóm đang bị ốm mệt lúc 1 giờ trưa. Nếu là chủ nhà, em xử lí thế nào?', 'Nhẹ nhàng mời các bạn tạm dừng trò chơi ồn ào giờ nghỉ trưa để bà cụ ốm nghỉ ngơi, chuyển sang chơi cờ hay đọc truyện êm trong nhà', ['Hò hét to hơn nữa át tiếng ho của bà cụ', 'Bảo các bạn chạy ra hành lang đập cửa nhà bà', 'Kệ cho bạn la hét vì nhà mình có quyền vui'],
               'Nhạy cảm quan tâm sức khỏe hàng xóm ngay cả khi nhà có khách vui thể hiện nếp sống cực kì văn minh.', 'Giữ trật tự khi hàng xóm ốm'),
            _q(5, 8, 'application', 'Khu dân cư tổ chức phong trào "Ngõ xóm Sáng – Xanh – Sạch – Thân thiện". Bốn cụm dân cư thi đua trồng chậu hoa treo trước cửa nhà. Theo biểu đồ dưới đây, tổng cộng cả 4 cụm đã trang trí được bao nhiêu chậu hoa làm đẹp ngõ xóm?', '60 chậu hoa (15 + 18 + 12 + 15 = 60)', ['50 chậu hoa', '55 chậu hoa', '65 chậu hoa'],
               '15 + 18 + 12 + 15 = 60 chậu hoa rực rỡ khoe sắc gắn kết tình cảm láng giềng!', 'Đọc biểu đồ Ngõ xóm Xanh',
               fig=bars_fig('Chậu hoa trang trí ngõ xóm chung', ['Cụm 1', 'Cụm 2', 'Cụm 3', 'Cụm 4'], [15, 18, 12, 15], 'chậu')),
            _q(5, 9, 'application', 'Buổi chiều bố mẹ em nấu một nồi chè hạt sen rất ngon, bảo em mang một bát sang biếu ông bà hàng xóm bên cạnh. Em cần thực hiện như thế nào để thể hiện sự kính trọng và chu đáo?', 'Bưng khay đựng bát chè bằng hai tay cẩn thận (tránh nóng đổ), gõ cửa nhẹ nhàng lễ phép chào ông bà và nói: "Dạ cháu mời ông bà dùng chè nhà cháu mới nấu ạ!"', ['Chạy thục mạng làm sánh đổ một nửa rồi đặt xuống bậc thềm chạy về', 'Ăn thử một nửa bát trước rồi mới mang sang', 'Đứng ngoài cổng hét to bảo ông bà tự ra lấy'],
               'Nét đẹp "chia sẻ món ngon hàng xóm" của người Việt luôn giữ lửa yêu thương giữa thời đại bận rộn!', 'Lễ phép biếu quà hàng xóm'),
            _q(5, 10, 'application', 'Bạn Minh vô tình sút quả bóng nhựa bay qua tường rào rơi đúng vào chậu cây cảnh của nhà bác Tư hàng xóm làm đổ đất ra sân (may mắn chậu không vỡ). Minh nên làm gì?', 'Sang bấm chuông xin phép bác Tư nhận lỗi, tự tay dọn sạch đất vun lại gọn vào chậu rồi mới xin lại bóng và hứa chơi cẩn thận ở sân rộng', ['Trèo rào lén sang lấy trộm bóng rồi chạy biến để mặc sân nhà bác bẩn', 'Nói dối bảo quả bóng của một bạn lạ nào ném vào', 'Quát đòi bác Tư phải ném bóng trả ngay'],
               'Trung thực nhận lỗi và dọn dẹp sạch hậu quả giúp bác hàng xóm càng thêm yêu quý khen ngợi em!', 'Xử lí sự cố với hàng xóm'),
            _q(5, 11, 'application', 'Nhà bác hàng xóm ngay sát vách về quê ăn giỗ 2 ngày, trước khi đi bác nhờ mẹ em thỉnh thoảng ngó giúp giàn hoa phong lan nhưng sáng nay trời bỗng đổ mưa giông kèm gió lớn có nguy cơ làm rơi chậu lan treo ngoài ban công nhà bác. Em có thể nhắc bố mẹ giúp bác việc gì?', 'Nhắc bố mẹ gọi báo bác ngay hoặc phối hợp bảo vệ tòa nhà kéo che chắn kịp thời để giữ an toàn tài sản giúp bác hàng xóm', ['Đứng cười nhìn chậu hoa rơi vỡ cho vui', 'Nhân lúc bác vắng nhà sang hái trộm hết hoa lan', 'Không nói gì với bố mẹ cả'],
               'Chủ động để ý bảo vệ tài sản giúp láng giềng lúc họ đi vắng là nghĩa cử cao đẹp tuyệt vời!', 'Giúp láng giềng lúc đi vắng'),
            _q(5, 12, 'application', 'Nếu một người bạn hàng xóm cùng tuổi ở nhà bên cạnh có chút hiềm khích cãi nhau nhỏ với em về chỗ để xe đạp trong ngõ chung, em nên giải quyết thế nào cho êm đẹp?', 'Bình tĩnh nói chuyện thẳng thắn nhẹ nhàng, cùng chia đôi vạch gọn gàng không gian để xe cho cả hai nhà rộng lối đi chứ không cãi cọ gây phiền bố mẹ hai bên', ['Đẩy đổ xe đạp của bạn ra giữa đường xe chạy', 'Cấm bạn không bao giờ được đi qua trước cửa nhà mình', 'Gọi cả nhóm bạn ở trường về gây gổ'],
               'Thương lượng gọn gàng chỗ để xe chung thể hiện lối sống văn minh của công dân nhí!', 'Giải quyết mâu thuẫn ngõ chung'),
            _q(5, 13, 'advanced', 'Ngõ nhỏ nơi em ở có 8 gia đình sinh sống hai bên dãy nhà (mỗi bên 4 nhà). Dịp Tết cổ truyền, mẹ chuẩn bị mỗi gia đình hàng xóm 2 chiếc bánh chưng xanh tự gói (tính tặng cả 7 gia đình hàng xóm xung quanh). Hỏi mẹ cần gói riêng để đem biếu láng giềng tất cả bao nhiêu chiếc bánh chưng?', '14 chiếc bánh chưng', ['16 chiếc bánh chưng', '7 chiếc bánh chưng', '10 chiếc bánh chưng'],
               '8 gia đình trừ nhà mình còn 7 nhà hàng xóm -> 7 x 2 = 14 chiếc bánh chưng ấm tình ngày Tết!', 'Tết ấm tình làng xóm'),
            _q(5, 14, 'advanced', 'Tại sao ở các thành phố lớn với nhiều tòa chung cư hiện đại cửa đóng then cài, việc dạy trẻ em biết chào hỏi và quan tâm hàng xóm lại càng trở nên cực kì quan trọng hơn bao giờ hết?', 'Vì lối sống khép kín dễ làm con người xa cách; lời chào hỏi trong thang máy và sự quan tâm chân thành giúp chung cư văn minh an toàn hơn', ['Vì sống chung cư không có ai là bạn bè', 'Vì ở chung cư cần mở toang cửa cả ngày lẫn đêm', 'Vì chỉ ở nông thôn mới có hàng xóm'],
               'Xây dựng "chung cư văn minh tình nghĩa" bắt đầu từ lời chào ấm áp của những đứa trẻ!', 'Tình láng giềng trong đô thị hiện đại'),
            _q(5, 15, 'advanced', 'Giữa "Thân thiện hỏi thăm quan tâm hàng xóm đúng mực" và "Tò mò xoi mói nói chuyện riêng tư của nhà hàng xóm", ranh giới văn minh nằm ở đâu?', 'Ở sự TÔN TRỌNG QUYỀN RIÊNG TƯ: sẵn lòng giúp đỡ, chào hỏi lễ phép nhưng tuyệt đối không nhìn trộm, nghe lén hay bàn tán chuyện riêng nhà khác', ['Hai việc hoàn toàn giống nhau không có ranh giới', 'Quan tâm là phải biết hết mọi bí mật nhà bên cạnh', 'Không cần chào hỏi ai là tôn trọng nhất'],
               'Chân thành kết hợp tinh tế tôn trọng sự riêng tư làm tình làng nghĩa xóm bền chặt văn minh!', 'Ranh giới giữa Quan tâm và Xoi mói'),
        ]
    ))

    # BÀI 6: Tích cực tham gia việc lớp, việc trường
    lessons.append(make_lesson(
        'daoduc3-c2', 'daoduc3-b06', 'Bài 6. Tích cực Tham gia Việc lớp, Việc trường', 6,
        'Nhận biết ý nghĩa của công việc tập thể lớp trường (vệ sinh, trang trí, phong trào Đội/Sao Nhi đồng) và tự giác hợp tác tích cực đóng góp công sức',
        ['Tham gia việc lớp trường', 'Tinh thần tập thể', 'Hợp tác Sao Nhi đồng'],
        [
            _q(6, 1, 'basic', 'Những hoạt động nào sau đây thuộc về "Việc lớp, Việc trường" mà mỗi bạn nhỏ lớp 3 cần hào hứng tham gia cùng tập thể?', 'Trực nhật giữ lớp sạch đẹp, chăm sóc cây xanh công trình măng non, trang trí góc học tập và tham gia hội khỏe, phong trào Kế hoạch nhỏ', ['Chỉ làm mỗi bài kiểm tra cá nhân của riêng mình', 'Ngồi nhìn các bạn làm rồi chê bai', 'Chạy trốn ra ngoài mỗi khi lớp dọn vệ sinh chung'],
               'Mái trường là ngôi nhà chung; mỗi đóng góp nhỏ của em giúp lớp học trở nên ấm áp và tự hào hơn.', 'Nhận biết việc lớp việc trường',
               fig=table_fig('Góp sức Việc lớp Trường', ['Hoạt động', 'Cách tham gia'], [['Trực nhật lớp', 'Đến sớm, làm đúng'], ['Công trình xanh', 'Nhổ cỏ, tưới cây lớp'], ['Văn nghệ, thể thao', 'Tập luyện, cổ vũ bạn'], ['Họp lớp góp ý', 'Nêu ý tưởng xây dựng']])),
            _q(6, 2, 'basic', 'Khi tham gia vào hoạt động lao động vệ sinh sân trường ngày cuối tuần cùng cả lớp 3, thái độ đúng nhất của em là gì?', 'Vui vẻ nhận phần việc phù hợp sức mình (như nhặt rác lá khô, lau cửa sổ tầng trệt), làm nghiêm túc cùng bạn bè và giữ an toàn dụng cụ', ['Đứng khoanh tay chỉ trỏ ra lệnh cho bạn khác làm hết', 'Lấy chổi phất bụi lên người bạn để đùa nghịch', 'Lén bỏ về nhà sớm trước khi xong việc'],
               'Cùng nhau lao động vui vẻ không chỉ làm trường sạch đẹp mà còn gắn kết tình bạn vô cùng kì diệu!', 'Thái độ khi lao động tập thể'),
            _q(6, 3, 'basic', 'Ở lớp 3, các em được chuẩn bị rèn luyện phấn đấu để đứng vào hàng ngũ Đội Thiếu niên Tiền phong Hồ Chí Minh (đeo khăn quàng đỏ thắm). Điều này đòi hỏi em rèn luyện điều gì?', 'Thực hiện tốt 5 điều Bác Hồ dạy, tích cực tham gia các phong trào thi đua học tốt – việc tốt của Chi đội, Sao Nhi đồng và luôn gương mẫu đi đầu', ['Không cần học chỉ cần mua khăn quàng đỏ đeo là xong', 'Chỉ cần chạy nhanh nhất lớp', 'Chỉ tham gia khi được tặng quà'],
               'Phấn đấu trở thành Đội viên gương mẫu là niềm tự hào lớn nhất của lứa tuổi lớp 3 Tiểu học!', 'Phấn đấu trở thành Đội viên'),
            _q(6, 4, 'basic', 'Trong một cuộc thi Kéo co hoặc Nhảy bao bố hội thao toàn trường, nếu em không nằm trong đội hình thi đấu chính thức của lớp mà ngồi trên hàng khán giả, em vẫn có thể đóng góp gì cho việc lớp?', 'Cổ vũ nhiệt tình văn minh bằng tiếng vỗ tay và lời reo cổ động tinh thần bạn thi đấu, giữ trật tự chỗ ngồi và phụ đưa nước cho bạn', ['Ngồi quay lưng lại đọc truyện không quan tâm kết quả', 'La ó chế giễu đội bạn khác lớp khi họ vấp ngã', 'Bày vỏ chai nước bừa bãi khắp khán đài'],
               'Cổ động viên nhiệt tình và văn minh chính là nguồn sức mạnh tinh thần tiếp lửa cho cả lớp chiến thắng!', 'Vai trò cổ vũ tập thể'),
            _q(6, 5, 'basic', 'Khi cô giáo chủ nhiệm tổ chức họp lớp bầu ban cán sự hoặc thảo luận nội quy góc sáng tạo của lớp, em nên thể hiện tinh thần làm chủ tập thể thế nào?', 'Chú ý lắng nghe các ý kiến, mạnh dạn giơ tay đóng góp ý tưởng thiết thực và tôn trọng biểu quyết đa số của cả lớp', ['Ngồi gục mặt xuống bàn không nói lời nào rồi ra ngoài chê sau lưng', 'Chỉ đồng ý nếu mọi người nghe theo 100% ý của mình', 'Nói chuyện riêng suốt buổi họp lớp'],
               'Tham gia ý kiến xây dựng lớp học dân chủ giúp mọi quy định được thực hiện tự nguyện và vui vẻ nhất.', 'Tham gia xây dựng nội quy lớp'),
            _q(6, 6, 'basic', 'Lợi ích tuyệt vời đối với chính bản thân em khi nhiệt tình tham gia các hoạt động phong trào của lớp và nhà trường là gì?', 'Trở nên tự tin năng động hơn, kết thêm nhiều bạn tốt, rèn kĩ năng làm việc nhóm và có thật nhiều kỉ niệm tuổi thơ rực rỡ khó quên', ['Làm giảm sút trí nhớ không học được Toán', 'Khiến bạn bè xa lánh ghét bỏ', 'Không có lợi ích nào ngoài mệt mỏi'],
               'Phát triển toàn diện cả tri thức sách vở lẫn kĩ năng xã hội tạo nên học sinh năng động tự tin!', 'Lợi ích khi tham gia phong trào'),
            _q(6, 7, 'application', 'Lớp 3A chuẩn bị trang trí lớp chào mừng ngày 20/11 với chủ đề "Mái trường Yêu thương". Bạn Mai vẽ rất khéo, bạn Tùng cắt dán đẹp, còn bạn An chữ hơi xấu một chút nhưng lại rất khỏe nhanh nhẹn. Nhóm nên phân công việc cho An thế nào để ai cũng thấy mình có ích?', 'Giao cho An phụ trách sắp xếp kê bàn ghế thẳng hàng, mang vật liệu hồ dán, giữ thang an toàn khi cô dán chữ cao và thu gom giấy vụn giữ sàn lớp sạch sẽ', ['Bảo An ngồi im một góc vì chữ xấu không làm được gì', 'Ép An phải viết chữ thật nhiều cho xấu cả tờ báo tường', 'Đuổi An ra khỏi lớp ngồi ngoài hành lang'],
               'Phân công đúng sở trường giúp mọi thành viên trong lớp đều tỏa sáng đóng góp vào thành công chung!', 'Phân công theo thế mạnh'),
            _q(6, 8, 'application', 'Khối 3 tổ chức ngày hội "Kế hoạch nhỏ" thu gom vỏ lon nhôm và giấy báo cũ gây quỹ giúp bạn nghèo. Theo biểu đồ đóng góp của 4 lớp khối 3 dưới đây, tổng số ki-lô-gam vật liệu tái chế cả khối thu được là bao nhiêu?', '140 kg (35 + 40 + 30 + 35 = 140)', ['120 kg', '130 kg', '150 kg'],
               '35 + 40 + 30 + 35 = 140 kg vật liệu tái chế – vừa sạch môi trường vừa đầy ắp nghĩa tình!', 'Đọc biểu đồ Kế hoạch nhỏ',
               fig=bars_fig('Kế hoạch nhỏ thu gom khối 3 (kg)', ['Lớp 3A', 'Lớp 3B', 'Lớp 3C', 'Lớp 3D'], [35, 40, 30, 35], 'kg')),
            _q(6, 9, 'application', 'Trong buổi lao động nhổ cỏ bồn hoa sân trường, một số bạn thấy hơi nắng và mệt nên định ngồi tụm lại chơi oẳn tù tì mặc kệ mấy bạn còn lại làm nốt phần cỏ dày nhất. Em nên khích lệ các bạn thế nào?', 'Nói vui vẻ cùng làm: "Cố lên các bạn ơi chỉ còn một góc nhỏ nữa thôi, cả nhóm cùng xúm vào 5 phút là xong sạch đẹp ngay để cùng nhau ra bóng râm uống nước nhé!"', ['Ngồi xuống chơi oẳn tù tì chung với các bạn trốn việc', 'Quát mắng các bạn ấy là đồ lười biếng', 'Bỏ về lớp trước luôn'],
               'Lời động viên tích cực biến công việc nặng nhọc thành niềm vui hợp tác tập thể!', 'Khích lệ bạn khi làm việc chung'),
            _q(6, 10, 'application', 'Lớp em nhận chăm sóc một đoạn hành lang xanh gồm 10 chậu cây trầu bà. Sáng nay đi qua em thấy một chậu cây bị gió xô nghiêng rơi ít đất ra hành lang dù hôm nay KHÔNG PHẢI phiên trực nhật của tổ em. Em làm gì?', 'Chủ động dựng ngay chậu cây đứng vững vào góc tường an toàn, quét gọn phần đất rơi bỏ gốc cây vì giữ đẹp lớp là việc chung mỗi ngày của mọi thành viên', ['Bước qua luôn vì hôm nay không phải lịch trực của tổ mình', 'Đá thêm cho chậu cây đổ hẳn xuống vỡ luôn', 'Chụp ảnh đổ lỗi cho tổ trực nhật hôm nay'],
               'Tinh thần "Mình vì mọi người" vượt qua ranh giới lịch trực nhật cứng nhắc làm nên tập thể lớp tuyệt vời!', 'Chủ động không so đo phiên trực'),
            _q(6, 11, 'application', 'Đội văn nghệ lớp 3B chuẩn bị biểu diễn múa hát sân trường cần tập luyện vào 30 phút cuối chiều thứ Tư và thứ Sáu trong 2 tuần. Bạn Lan đã đăng kí tham gia đội văn nghệ từ đầu, nhưng hôm thứ Sáu trùng lịch có bộ phim hoạt hình hay ở nhà. Lan cần lựa chọn ra sao?', 'Giữ đúng cam kết tập luyện đều đặn cùng đội văn nghệ lớp để đủ người ghép đội hình; phim hoạt hình có thể xem lại cuối tuần', ['Nghỉ tập đột xuất không báo ai để về xem phim hoạt hình', 'Đến tập nhưng đứng khoanh tay không chịu múa theo nhịp', 'Rủ thêm 3 bạn khác nghỉ tập cùng'],
               'Đặt lợi ích tập thể lên trên sở thích nhất thời giữ cho đội hình tiết mục thành công rực rỡ!', 'Trách nhiệm với đội hình lớp'),
            _q(6, 12, 'application', 'Khi một lớp khác (lớp 3D) giành giải Nhất cuộc thi Báo tường 20/11 còn lớp mình (lớp 3A) đạt giải Nhì, thái độ thể thao văn minh nhất của cả lớp 3A là gì?', 'Vỗ tay chúc mừng lớp 3D, sang tham quan học hỏi nét sáng tạo hay trong tờ báo tường bạn và vui mừng tự hào về giải Nhì nỗ lực của lớp mình', ['Nói xấu ban giám khảo chấm thiên vị bất công', 'Chê tờ báo tường giải Nhất của lớp 3D xấu tệ', 'Xé bảng kết quả thi đua trường'],
               'Tôn trọng chiến thắng của bạn và trân trọng thành quả của mình là phong thái cao thượng tuyệt vời.', 'Tinh thần thi đua lành mạnh'),
            _q(6, 13, 'advanced', 'Một lớp học 32 bạn chia đều thành 4 tổ trực nhật luân phiên từ thứ Hai đến thứ Năm (mỗi ngày 1 tổ gồm 8 bạn làm sạch lớp); riêng ngày thứ Sáu cuối tuần cả 4 tổ cùng tổng vệ sinh chung trong 15 phút. Nếu mỗi ngày trực nhật thường một tổ mất 10 phút, hỏi trong 1 tuần học cả lớp đã dành tổng cộng bao nhiêu phút làm việc chăm sóc lớp (tính thời gian thực tế mỗi ngày)?', '55 phút (4 ngày x 10 phút + 15 phút tổng vệ sinh = 55 phút)', ['40 phút', '45 phút', '95 phút'],
               'Thứ 2, 3, 4, 5 mỗi ngày 10 phút = 40 phút; thứ 6 thêm 15 phút tổng vệ sinh = 55 phút – chưa tới 1 giờ mỗi tuần mà lớp luôn sạch bong!', 'Tính quỹ thời gian chăm sóc lớp'),
            _q(6, 14, 'advanced', 'Vì sao người ta ví một tập thể lớp đoàn kết tích cực giống như "Một dàn nhạc giao hưởng"?', 'Vì mỗi nhạc cụ có âm thanh riêng nhưng khi hòa nhịp đều tạo bản nhạc hay; trong lớp mỗi bạn một sở trường cùng góp sức sẽ tạo tập thể mạnh', ['Vì lớp học lúc nào cũng phải phát ra tiếng ồn to như dàn nhạc', 'Vì chỉ có lớp trưởng là nhạc trưởng được làm việc', 'Vì âm nhạc không liên quan gì đến việc lớp'],
               'Ẩn dụ dàn nhạc tôn vinh sự kết hợp hài hòa giữa trách nhiệm cá nhân và sức mạnh tập thể!', 'Ẩn dụ Dàn nhạc tập thể'),
            _q(6, 15, 'advanced', 'Có bạn nói: "Tớ học thật giỏi các môn chính lấy điểm 10 là đủ rồi, mấy việc trang trí lớp hay phong trào Kế hoạch nhỏ không quan trọng nên không cần tham gia". Em phản hồi nhận xét này thế nào?', 'Học giỏi rất tốt, nhưng tham gia việc lớp giúp rèn kĩ năng sống, tinh thần đồng đội và trách nhiệm mà sách vở không dạy hết được', ['Đúng rồi, chỉ cần học làm bài thi còn việc lớp cứ để các bạn khác làm', 'Đúng rồi, tham gia phong trào chỉ làm mất điểm thi', 'Phong trào trường học chỉ dành cho lớp 1'],
               'Phát triển cân bằng giữa Tri thức – Kĩ năng xã hội – Trách nhiệm tập thể tạo nên học sinh xuất sắc toàn diện!', 'Cân bằng học tập và phong trào'),
        ]
    ))

    return lessons
